from itertools import permutations, combinations

def fmt(minutes):
    h = minutes // 60
    m = minutes % 60
    suffix = "AM" if h < 12 else "PM"
    h12 = h % 12
    if h12 == 0:
        h12 = 12
    return f"{h12}:{m:02d}{suffix}"

# Travel times (minutes), directed
T = {
    "Fisherman's Wharf": {
        "Presidio": 17, "Richmond District": 18, "Financial District": 11
    },
    "Presidio": {
        "Fisherman's Wharf": 19, "Richmond District": 7, "Financial District": 23
    },
    "Richmond District": {
        "Fisherman's Wharf": 18, "Presidio": 7, "Financial District": 22
    },
    "Financial District": {
        "Fisherman's Wharf": 10, "Presidio": 22, "Richmond District": 21
    }
}

# Friend data: name -> (location, window_start_min, window_end_min, min_meeting_min)
friends = {
    "Emily":   ("Presidio",            16*60 + 15, 21*60 + 0,  105),  # 4:15PM-9:00PM, 105 min
    "Joseph":  ("Richmond District",   17*60 + 15, 22*60 + 0,  120),  # 5:15PM-10:00PM, 120 min
    "Melissa": ("Financial District",  15*60 + 45, 21*60 + 45,  75),  # 3:45PM-9:45PM, 75 min
}

start_loc = "Fisherman's Wharf"
start_time = 9*60  # 9:00AM

def schedule_for_order(order):
    steps = [f"You start at {start_loc} at {fmt(start_time)}."]
    curr_loc = start_loc
    curr_time = start_time
    total_wait = 0
    total_travel = 0

    for name in order:
        loc, w_start, w_end, need = friends[name]
        travel = T[curr_loc][loc]
        # Just-in-time departure if arriving too early
        earliest_arrival = curr_time + travel
        if earliest_arrival < w_start:
            depart = w_start - travel
            if depart > curr_time:
                steps.append(f"You wait until {fmt(depart)}.")
                total_wait += (depart - curr_time)
                curr_time = depart

        # Travel
        curr_time += travel
        total_travel += travel
        steps.append(f"You travel to {loc} in {travel} minutes and arrive at {fmt(curr_time)}.")

        # Meeting
        meet_start = max(curr_time, w_start)
        meet_end = meet_start + need
        if meet_end > w_end:
            return None  # infeasible
        # If arrival is before meet_start (shouldn't happen with just-in-time, but guard anyway)
        if curr_time < meet_start:
            steps.append(f"You wait until {fmt(meet_start)}.")
            total_wait += (meet_start - curr_time)
        steps.append(f"You meet {name} for {need} minutes from {fmt(meet_start)} to {fmt(meet_end)}.")
        curr_loc = loc
        curr_time = meet_end

    return {
        "steps": steps,
        "finish_time": curr_time,
        "count": len(order),
        "total_wait": total_wait,
        "total_travel": total_travel
    }

# Search best schedule: maximize count, then minimize finish time, then minimize wait, then minimize travel
best = None
friend_names = list(friends.keys())
# Try sizes 3 down to 1
for k in range(len(friend_names), 0, -1):
    found_any = False
    for subset in combinations(friend_names, k):
        for order in permutations(subset):
            result = schedule_for_order(order)
            if result is None:
                continue
            found_any = True
            if best is None:
                best = result
            else:
                # Compare by objectives
                b = best
                r = result
                if (
                    (r["count"] > b["count"]) or
                    (r["count"] == b["count"] and r["finish_time"] < b["finish_time"]) or
                    (r["count"] == b["count"] and r["finish_time"] == b["finish_time"] and r["total_wait"] < b["total_wait"]) or
                    (r["count"] == b["count"] and r["finish_time"] == b["finish_time"] and r["total_wait"] == b["total_wait"] and r["total_travel"] < b["total_travel"])
                ):
                    best = r
    if found_any:
        # If we found any schedule with k friends, no need to look at smaller k
        break

# Output the chosen plan as a list of strings
print(best["steps"] if best else ["No feasible schedule."])

from itertools import combinations, permutations

def to_minutes(s):
    # s like '9:00AM' or '4:15PM'
    s = s.strip().upper()
    am = s.endswith('AM')
    pm = s.endswith('PM')
    s = s[:-2]
    hour, minute = map(int, s.split(':'))
    if am:
        if hour == 12:
            hour = 0
    elif pm:
        if hour != 12:
            hour += 12
    return hour * 60 + minute

def fmt_time(m):
    hour = (m // 60) % 24
    minute = m % 60
    period = 'AM' if hour < 12 else 'PM'
    h12 = hour % 12
    if h12 == 0:
        h12 = 12
    return f"{h12}:{minute:02d}{period}"

# Directed travel times (minutes)
travel = {
    'Sunset District': {
        'North Beach': 29,
        'Union Square': 30,
        'Alamo Square': 17,
    },
    'North Beach': {
        'Sunset District': 27,
        'Union Square': 7,
        'Alamo Square': 16,
    },
    'Union Square': {
        'Sunset District': 26,
        'North Beach': 10,
        'Alamo Square': 15,
    },
    'Alamo Square': {
        'Sunset District': 16,
        'North Beach': 15,
        'Union Square': 14,
    }
}

# Friends and constraints
friends = [
    {
        'name': 'Sarah',
        'location': 'North Beach',
        'start': to_minutes('4:00PM'),
        'end': to_minutes('6:15PM'),
        'min_duration': 60
    },
    {
        'name': 'Jeffrey',
        'location': 'Union Square',
        'start': to_minutes('3:00PM'),
        'end': to_minutes('10:00PM'),
        'min_duration': 75
    },
    {
        'name': 'Brian',
        'location': 'Alamo Square',
        'start': to_minutes('4:00PM'),
        'end': to_minutes('5:30PM'),
        'min_duration': 75
    }
]

start_location = 'Sunset District'
start_time = to_minutes('9:00AM')

def try_order(order, start_loc, start_t):
    lines = []
    current_loc = start_loc
    t = start_t
    total_travel = 0
    total_meet = 0

    # First line: starting point
    if not lines:
        lines.append(f"You start at {start_loc} at {fmt_time(start_t)}.")

    for fr in order:
        loc = fr['location']
        # Travel
        if current_loc == loc:
            travel_time = 0
        else:
            if current_loc not in travel or loc not in travel[current_loc]:
                return None  # no edge
            travel_time = travel[current_loc][loc]
            t_arrive = t + travel_time
            total_travel += travel_time
            lines.append(f"You travel to {loc} in {travel_time} minutes and arrive at {fmt_time(t_arrive)}.")
            t = t_arrive
            current_loc = loc

        # Wait if early
        earliest_start = max(t, fr['start'])
        latest_start = fr['end'] - fr['min_duration']

        if t > latest_start:
            return None  # infeasible
        if t < earliest_start:
            lines.append(f"You wait until {fmt_time(earliest_start)}.")
        meet_start = earliest_start
        meet_end = meet_start + fr['min_duration']
        if meet_end > fr['end']:
            return None  # infeasible

        lines.append(f"You meet {fr['name']} for {fr['min_duration']} minutes from {fmt_time(meet_start)} to {fmt_time(meet_end)}.")
        total_meet += fr['min_duration']
        t = meet_end

    return {
        'lines': lines,
        'count': len(order),
        'total_meet': total_meet,
        'total_travel': total_travel,
        'end_time': t
    }

best = None
best_key = None

# Enumerate subsets by descending size, and permutations
for r in range(len(friends), 0, -1):
    found_any = False
    for subset in combinations(friends, r):
        for order in permutations(subset):
            res = try_order(order, start_location, start_time)
            if res is None:
                continue
            found_any = True
            # Score: maximize count, then total_meet, then minimize travel, then minimize end time
            key = (res['count'], res['total_meet'], -res['total_travel'], -res['end_time'])
            if best is None or key > best_key:
                best = res
                best_key = key
    if found_any:
        break  # we have the maximum number of friends met

# Output schedule lines
if best is None:
    schedule = [f"You start at {start_location} at {fmt_time(start_time)}.", "No feasible meetings given the constraints."]
else:
    schedule = best['lines']

print(schedule)

from itertools import permutations, combinations

# Time helpers
BASE_HOUR = 9  # Start at 9:00AM => minutes are offset from 9:00
def minutes_to_time_str(m):
    hour24 = BASE_HOUR + m // 60
    minute = m % 60
    period = "AM" if hour24 < 12 else "PM"
    hour12 = hour24 % 12
    if hour12 == 0:
        hour12 = 12
    return f"{hour12}:{minute:02d}{period}"

# Travel times (directed, in minutes)
travel = {
    "Richmond District": {
        "Sunset District": 11,
        "Haight-Ashbury": 10,
        "Mission District": 20,
        "Golden Gate Park": 9,
    },
    "Sunset District": {
        "Richmond District": 12,
        "Haight-Ashbury": 15,
        "Mission District": 24,
        "Golden Gate Park": 11,
    },
    "Haight-Ashbury": {
        "Richmond District": 10,
        "Sunset District": 15,
        "Mission District": 11,
        "Golden Gate Park": 7,
    },
    "Mission District": {
        "Richmond District": 20,
        "Sunset District": 24,
        "Haight-Ashbury": 12,
        "Golden Gate Park": 17,
    },
    "Golden Gate Park": {
        "Richmond District": 7,
        "Sunset District": 10,
        "Haight-Ashbury": 7,
        "Mission District": 17,
    },
}

# Friend data: location, (window_start, window_end), duration
# Times are minutes after 9:00AM
friends = {
    "Sarah": {
        "location": "Sunset District",
        "window": (105, 600),   # 10:45AM to 7:00PM
        "duration": 30,
    },
    "Richard": {
        "location": "Haight-Ashbury",
        "window": (165, 405),   # 11:45AM to 3:45PM
        "duration": 90,
    },
    "Elizabeth": {
        "location": "Mission District",
        "window": (120, 495),   # 11:00AM to 5:15PM
        "duration": 120,
    },
    "Michelle": {
        "location": "Golden Gate Park",
        "window": (555, 705),   # 6:15PM to 8:45PM
        "duration": 90,
    },
}

start_location = "Richmond District"
start_time = 0  # minutes after 9:00AM

def build_schedule(order):
    """Build a schedule for a given order of friends.
       Returns (steps, total_wait, finish_time, total_travel) if feasible, else None.
    """
    steps = []
    steps.append(f"You start at {start_location} at {minutes_to_time_str(start_time)}.")
    time = start_time
    loc = start_location
    total_wait = 0
    total_travel = 0

    for name in order:
        info = friends[name]
        dest = info["location"]
        win_start, win_end = info["window"]
        duration = info["duration"]

        # Travel
        if loc == dest:
            t_travel = 0
        else:
            if loc not in travel or dest not in travel[loc]:
                return None  # missing edge
            t_travel = travel[loc][dest]
        arr_time = time + t_travel

        # Feasibility check before committing steps:
        earliest_start = max(arr_time, win_start)
        latest_start = win_end - duration
        if earliest_start > latest_start:
            return None  # cannot fit

        # Commit travel step
        if t_travel > 0:
            steps.append(
                f"You travel to {dest} in {t_travel} minutes and arrive at {minutes_to_time_str(arr_time)}."
            )
            total_travel += t_travel
        else:
            steps.append(
                f"You are already at {dest} and the time is {minutes_to_time_str(arr_time)}."
            )

        # Wait if early
        if arr_time < win_start:
            steps.append(f"You wait until {minutes_to_time_str(win_start)}.")
            total_wait += (win_start - arr_time)
            start_meet = win_start
        else:
            start_meet = arr_time

        end_meet = start_meet + duration
        # Meeting step
        steps.append(
            f"You meet {name} for {duration} minutes from {minutes_to_time_str(start_meet)} to {minutes_to_time_str(end_meet)}."
        )

        # Update state
        time = end_meet
        loc = dest

    return steps, total_wait, time, total_travel

# Search best plan:
best = None  # tuple: (num_met, total_wait, finish_time, total_travel, steps)
names = list(friends.keys())

found = False
for k in range(len(names), 0, -1):
    best_k = None
    for subset in combinations(names, k):
        for order in permutations(subset):
            res = build_schedule(order)
            if res is None:
                continue
            steps, wait_time, finish_time, travel_time = res
            score = (k, -wait_time, -finish_time, -travel_time)  # maximize k, then minimize wait, finish, travel
            if best_k is None:
                best_k = (score, steps)
            else:
                if score > best_k[0]:
                    best_k = (score, steps)
    if best_k is not None:
        best = best_k
        break

# Output
if best is None:
    plan = ["No feasible schedule found."]
else:
    plan = best[1]

# Print or return the plan list
print(plan)

from itertools import permutations

# Time helpers
def to_minutes(h, m=0):
    return h * 60 + m

def minutes_to_ampm(t):
    t = t % (24 * 60)
    hour = t // 60
    minute = t % 60
    ampm = "AM" if hour < 12 else "PM"
    hour12 = hour % 12
    if hour12 == 0:
        hour12 = 12
    return f"{hour12}:{minute:02d}{ampm}"

# Directed travel times (minutes)
travel = {
    "Bayview": {
        "Russian Hill": 23, "Alamo Square": 16, "North Beach": 21, "Financial District": 19
    },
    "Russian Hill": {
        "Bayview": 23, "Alamo Square": 15, "North Beach": 5, "Financial District": 11
    },
    "Alamo Square": {
        "Bayview": 16, "Russian Hill": 13, "North Beach": 15, "Financial District": 17
    },
    "North Beach": {
        "Bayview": 22, "Russian Hill": 4, "Alamo Square": 16, "Financial District": 8
    },
    "Financial District": {
        "Bayview": 19, "Russian Hill": 10, "Alamo Square": 17, "North Beach": 7
    }
}

# Friends data
friends = {
    "Joseph": {
        "location": "Russian Hill",
        "start": to_minutes(8, 30),
        "end": to_minutes(19, 15),
        "duration": 60
    },
    "Nancy": {
        "location": "Alamo Square",
        "start": to_minutes(11, 0),
        "end": to_minutes(16, 0),
        "duration": 90
    },
    "Jason": {
        "location": "North Beach",
        "start": to_minutes(16, 45),
        "end": to_minutes(21, 45),
        "duration": 15
    },
    "Jeffrey": {
        "location": "Financial District",
        "start": to_minutes(10, 30),
        "end": to_minutes(15, 45),
        "duration": 45
    }
}

start_loc = "Bayview"
start_time = to_minutes(9, 0)

def simulate_order(order):
    events = []
    total_wait = 0
    total_travel = 0
    current_loc = start_loc
    current_time = start_time

    events.append(f"You start at {start_loc} at {minutes_to_ampm(current_time)}.")

    for name in order:
        loc = friends[name]["location"]
        t = travel[current_loc][loc]
        total_travel += t
        arrive = current_time + t
        events.append(f"You travel to {loc} in {t} minutes and arrive at {minutes_to_ampm(arrive)}.")

        start_window = friends[name]["start"]
        end_window = friends[name]["end"]
        duration = friends[name]["duration"]

        # Wait if early
        meet_start = max(arrive, start_window)
        if arrive < start_window:
            wait_time = start_window - arrive
            total_wait += wait_time
            events.append(f"You wait until {minutes_to_ampm(meet_start)}.")

        # Check feasibility
        if meet_start + duration > end_window:
            return None  # invalid schedule for this order

        meet_end = meet_start + duration
        events.append(f"You meet {name} for {duration} minutes from {minutes_to_ampm(meet_start)} to {minutes_to_ampm(meet_end)}.")

        current_time = meet_end
        current_loc = loc

    finish_time = current_time
    return {
        "events": events,
        "count": len(order),
        "finish": finish_time,
        "wait": total_wait,
        "travel": total_travel
    }

# Enumerate all permutations of all friends; if none feasible for all four, consider smaller subsets
names = list(friends.keys())

best = None
best_key = None

# Try full set first, then smaller subsets if needed
found_any = False
for r in range(len(names), 0, -1):
    best_for_r = None
    best_key_for_r = None
    for order in permutations(names, r):
        result = simulate_order(order)
        if result is None:
            continue
        found_any = True
        # Key: maximize count, then minimize finish time, then minimize wait, then minimize travel
        key = (-result["count"], result["finish"], result["wait"], result["travel"])
        if best_for_r is None or key < best_key_for_r:
            best_for_r = result
            best_key_for_r = key
    if best_for_r is not None:
        best = best_for_r
        best_key = best_key_for_r
        break  # we found the maximum r achievable

# Output
if not found_any:
    itinerary = ["No feasible schedule found with the given constraints."]
else:
    itinerary = best["events"]

print(itinerary)

from itertools import combinations, permutations

def minutes(tstr):
    # "H:MMAM/PM" to minutes since midnight
    h, m = map(int, tstr[:-2].split(':'))
    ampm = tstr[-2:]
    if ampm.upper() == 'AM':
        return h % 12 * 60 + m
    else:
        return (h % 12 + 12) * 60 + m

def fmt(m):
    # minutes since midnight to "H:MMAM/PM"
    m = int(m)
    h = (m // 60) % 24
    mi = m % 60
    ampm = 'AM' if h < 12 else 'PM'
    h12 = h % 12
    if h12 == 0:
        h12 = 12
    return f"{h12}:{mi:02d}{ampm}"

# Directed travel times (minutes)
travel = {
    "Nob Hill": {
        "Presidio": 17, "North Beach": 8, "Fisherman's Wharf": 11, "Pacific Heights": 8
    },
    "Presidio": {
        "Nob Hill": 18, "North Beach": 18, "Fisherman's Wharf": 19, "Pacific Heights": 11
    },
    "North Beach": {
        "Nob Hill": 7, "Presidio": 17, "Fisherman's Wharf": 5, "Pacific Heights": 8
    },
    "Fisherman's Wharf": {
        "Nob Hill": 11, "Presidio": 17, "North Beach": 6, "Pacific Heights": 12
    },
    "Pacific Heights": {
        "Nob Hill": 8, "Presidio": 11, "North Beach": 9, "Fisherman's Wharf": 13
    }
}
for a in list(travel.keys()):
    travel[a][a] = 0

# Friends data
friends = [
    dict(name="Jeffrey", location="Presidio", start=minutes("8:00AM"), end=minutes("10:00AM"), min_dur=105),
    dict(name="Steven", location="North Beach", start=minutes("1:30PM"), end=minutes("10:00PM"), min_dur=45),
    dict(name="Barbara", location="Fisherman's Wharf", start=minutes("6:00PM"), end=minutes("9:30PM"), min_dur=30),
    dict(name="John", location="Pacific Heights", start=minutes("9:00AM"), end=minutes("1:30PM"), min_dur=15),
]

start_loc = "Nob Hill"
start_time = minutes("9:00AM")

def simulate(order):
    steps = [f"You start at {start_loc} at {fmt(start_time)}."]
    cur_loc = start_loc
    cur_time = start_time
    total_wait = 0

    # Helper: get friend by name
    f_by_name = {f['name']: f for f in friends}

    for i, name in enumerate(order):
        f = f_by_name[name]
        loc = f['location']
        t_travel = travel[cur_loc][loc]
        arrive = cur_time + t_travel
        steps.append(f"You travel to {loc} in {t_travel} minutes and arrive at {fmt(arrive)}.")

        # If arrival after latest feasible start for min duration -> infeasible
        latest_start = f['end'] - f['min_dur']
        if arrive > latest_start:
            return None  # infeasible

        # Wait if early
        meet_start = max(arrive, f['start'])
        if meet_start > latest_start:
            return None
        if meet_start > arrive:
            steps.append(f"You wait until {fmt(meet_start)}.")
            total_wait += (meet_start - arrive)

        # Minimal meeting end
        min_end = meet_start + f['min_dur']

        # Decide meeting end, possibly extend to reduce waiting for next friend
        if i < len(order) - 1:
            next_name = order[i+1]
            nf = f_by_name[next_name]
            t_to_next = travel[loc][nf['location']]
            latest_departure_to_hit_next_start = nf['start'] - t_to_next
            # Choose departure within [min_end, f['end']] to minimize future waiting
            dep = min(f['end'], max(min_end, latest_departure_to_hit_next_start))
            meet_end = dep
        else:
            # Last friend: finish at minimal end
            meet_end = min_end

        duration = meet_end - meet_start
        steps.append(f"You meet {name} for {duration} minutes from {fmt(meet_start)} to {fmt(meet_end)}.")

        # Advance
        cur_loc = loc
        cur_time = meet_end

    finish_time = cur_time
    return dict(steps=steps, finish=finish_time, waits=total_wait, met=len(order))

# Enumerate all schedules
names = [f['name'] for f in friends]
best = None

for r in range(1, len(names)+1):
    for subset in combinations(names, r):
        for order in permutations(subset):
            result = simulate(order)
            if result is None:
                continue
            if best is None:
                best = (result, order)
            else:
                br, _ = best
                # Primary: maximize number met
                if (result['met'] > br['met'] or
                    (result['met'] == br['met'] and result['finish'] < br['finish']) or
                    (result['met'] == br['met'] and result['finish'] == br['finish'] and result['waits'] < br['waits'])):
                    best = (result, order)

# Produce final schedule
if best is None:
    schedule = ["No feasible meetings given the constraints."]
else:
    schedule = best[0]['steps']

# Print the schedule list
print(schedule)

