            "type": "meet",
            "name": fr["name"],
            "location": fr["location"],
            "start_time": current_time,
            "end_time": current_time + fr["duration"],
            "minutes": fr["duration"]
        }
        events.append(meet_event)
        prev_meet_idx = len(events) - 1
        prev_friend_data = fr
        current_time += fr["duration"]

    finish_time = current_time
    return {
        "events": events,
        "finish_time": finish_time,
        "total_travel": total_travel,
        "met_count": len(order)
    }

