def simulate_order(order):
    steps = []
    current_loc = start_loc
    current_time = start_time
    waiting_total = 0
    travel_total = 0

    if not steps:
        steps.append(f"You start at {start_loc} at {minutes_to_str(start_time)}.")

    for name in order:
        f = friends[name]
        dest = f['location']
        if current_loc == dest:
            t_travel = 0
        else:
