        arrival = current_time + t_travel
        travel_total += t_travel
        if t_travel > 0:
            steps.append(f"You travel to {dest} in {t_travel} minutes and arrive at {minutes_to_str(arrival)}.")
        else:
            steps.append(f"You stay at {dest} and are already there at {minutes_to_str(arrival)}.")

        start_meet = max(arrival, f['start'])
        if start_meet > arrival:
            steps.append(f"You wait until {minutes_to_str(start_meet)}.")
            waiting_total += (start_meet - arrival)

        end_meet = start_meet + f['duration']
        if end_meet > f['end']:
            return None  # infeasible

        steps.append(f"You meet {name} for {f['duration']} minutes from {minutes_to_str(start_meet)} to {minutes_to_str(end_meet)}.")
        current_loc = dest
        current_time = end_meet

    return {
        'steps': steps,
        'met': len(order),
        'waiting': waiting_total,
        'travel': travel_total,
        'finish': current_time
    }

def find_best_schedule():
    names = list(friends.keys())
    best = None
    best_k = 0
    # Try largest number of friends first
    for k in range(len(names), 0, -1):
        candidates = []
        for order in permutations(names, k):
            res = simulate_order(order)
            if res is not None:
                candidates.append((order, res))
        if candidates:
            # Tie-break: min waiting, then min travel, then earliest finish
            candidates.sort(key=lambda x: (x[1]['waiting'], x[1]['travel'], x[1]['finish']))
            best_order, best = candidates[0]
            best_k = k
            return best  # maximize number met; we already sorted by tie-breaks
    return None

