        "Pacific Heights": 23, "Richmond District": 25, "Fisherman's Wharf": 25, "Golden Gate Park": 22
    }
}

# Friends: location, availability window (in minutes since midnight), and min meeting duration
def t(h, m):  # minutes since midnight
    return h * 60 + m

friends = {
    "Matthew":   {"loc": "Presidio",          "start": t(11, 0),  "end": t(21, 0),  "min": 90},
    "Margaret":  {"loc": "Chinatown",         "start": t(9, 15),  "end": t(18, 45), "min": 90},
    "Nancy":     {"loc": "Pacific Heights",   "start": t(14, 15), "end": t(17, 0),  "min": 15},
    "Helen":     {"loc": "Richmond District", "start": t(19, 45), "end": t(22, 0),  "min": 60},
    "Rebecca":   {"loc": "Fisherman's Wharf", "start": t(21, 15), "end": t(22, 15), "min": 60},
    "Kimberly":  {"loc": "Golden Gate Park",  "start": t(13, 0),  "end": t(16, 30), "min": 120},
    "Kenneth":   {"loc": "Bayview",           "start": t(14, 30), "end": t(18, 0),  "min": 60},
}

start_loc = "Russian Hill"
start_time = t(9, 0)

# DFS to explore feasible schedules
best = {
    "count": 0,
    "finish_time": start_time,
    "total_wait": 0,
    "total_travel": 0,
    "steps": [f"You start at {start_loc} at {format_time(start_time)}."]
}

def better_than(a, b):
    if a["count"] != b["count"]:
        return a["count"] > b["count"]
    if a["finish_time"] != b["finish_time"]:
        return a["finish_time"] < b["finish_time"]
    if a["total_wait"] != b["total_wait"]:
        return a["total_wait"] < b["total_wait"]
    return a["total_travel"] < b["total_travel"]

def dfs(curr_loc, curr_time, remaining, steps, total_travel, total_wait, met_count):
    global best
    candidate = {
        "count": met_count,
        "finish_time": curr_time,
        "total_wait": total_wait,
        "total_travel": total_travel,
        "steps": steps
    }
    if better_than(candidate, best):
        best = candidate

    # Upper bound pruning: even if we met all remaining, can't beat best
    if met_count + len(remaining) < best["count"]:
        return

    for name in list(remaining):
        info = friends[name]
        dest = info["loc"]
        # Travel time (if not defined, skip)
        if curr_loc not in travel or dest not in travel[curr_loc]:
            continue
        tt = travel[curr_loc][dest]
        arrival = curr_time + tt
        start = max(arrival, info["start"])
        end = start + info["min"]
        if end <= info["end"]:
            new_steps = steps.copy()
            new_steps.append(f"You travel to {dest} in {tt} minutes and arrive at {format_time(arrival)}.")
            if start > arrival:
                new_steps.append(f"You wait until {format_time(start)}.")
                extra_wait = start - arrival
            else:
                extra_wait = 0
            new_steps.append(f"You meet {name} for {info['min']} minutes from {format_time(start)} to {format_time(end)}.")
            new_remaining = set(remaining)
            new_remaining.remove(name)
            dfs(dest, end, new_remaining, new_steps, total_travel + tt, total_wait + extra_wait, met_count + 1)

# Run search
