            new_steps.append(f"You meet {name} for {info['min']} minutes from {format_time(start)} to {format_time(end)}.")
            new_remaining = set(remaining)
            new_remaining.remove(name)
            dfs(dest, end, new_remaining, new_steps, total_travel + tt, total_wait + extra_wait, met_count + 1)

