from functools import lru_cache

def feasible_next(cur_loc: str, cur_time: int, f: Friend) -> Optional[Tuple[int,int,int,int]]:
    # return (arrival_time, wait_time, start_time, end_time) if feasible, else None
    if cur_loc == f.location:
        tr = 0
    else:
        tr = travel[cur_loc][f.location]
