    start = max(arrival, f.start)
    end = start + f.min_dur
    if end <= f.end:
        wait = max(0, start - arrival)
        return (arrival, wait, start, end)
    return None

# Objective tie-breaker: maximize count; minimize waiting; minimize travel; earliest finish
def better(solA, solB):
    # sol = (count, total_wait, total_travel, finish_time, lines, visited_names)
    if solB is None:
        return True
    a = solA
    b = solB
    keys = [(a[0], b[0], True),             # maximize
            (-a[1], -b[1], True),           # minimize waiting
            (-a[2], -b[2], True),           # minimize travel
            (-a[3], -b[3], True)]           # earliest finish
    for (x, y, desc) in keys:
        if x > y:
            return True
        elif x < y:
            return False
    return False

best_solution = None

def dfs(cur_loc: str, cur_time: int, visited_mask: int, lines: List[str], total_wait: int, total_travel: int, visited_count: int):
    global best_solution
    # Bound: remaining potential
    remaining = len(friends) - bin(visited_mask).count('1')
    # Current solution candidate (no more meetings)
    current_finish = cur_time
    candidate = (visited_count, total_wait, total_travel, current_finish, lines, visited_mask)
    if better(candidate, best_solution):
        best_solution = candidate

    # Prune if even meeting all remaining friends cannot beat best
    if best_solution is not None:
        best_count = best_solution[0]
        if visited_count + remaining < best_count:
            return

    # Try all next friends
    for i, f in enumerate(friends):
        if (visited_mask >> i) & 1:
            continue
        feas = feasible_next(cur_loc, cur_time, f)
        if feas is None:
            continue
        arrival, wait, start, end = feas
        tr = 0 if cur_loc == f.location else travel[cur_loc][f.location]
        new_lines = lines.copy()
        # Travel line if needed
        if tr > 0:
            new_lines.append(f"You travel to {f.location} in {tr} minutes and arrive at {fmt_time(arrival)}.")
        else:
            # If no travel, we "arrive" immediately at same location; we can skip explicit arrival line
            pass
        if wait > 0:
            new_lines.append(f"You wait until {fmt_time(start)}.")
        new_lines.append(f"You meet {f.name} for {f.min_dur} minutes from {fmt_time(start)} to {fmt_time(end)}.")

        dfs(
            f.location, end, visited_mask | (1<<i), new_lines,
            total_wait + wait, total_travel + tr, visited_count + 1
        )

def build_schedule():
    start_lines = [f"You start at {START_LOC} at {fmt_time(START_TIME)}."]
    dfs(START_LOC, START_TIME, 0, start_lines, total_wait=0, total_travel=0, visited_count=0)
    # Return best schedule lines
    result = best_solution
    return result

