    t = t.strip().upper()
    ampm = t[-2:]
    hh, mm = t[:-2].split(':')
    hh = int(hh)
    mm = int(mm)
    if ampm == 'AM':
        if hh == 12:
            hh = 0
    else:
        if hh != 12:
            hh += 12
    return hh * 60 + mm

def fmt_time(m: int) -> str:
    m = m % (24*60)
    hh = m // 60
    mm = m % 60
    ampm = 'AM'
    if hh == 0:
        disp_h = 12
    elif hh < 12:
        disp_h = hh
    elif hh == 12:
        disp_h = 12
        ampm = 'PM'
    else:
        disp_h = hh - 12
        ampm = 'PM'
    if hh >= 12:
        ampm = 'PM'
    else:
        ampm = 'AM'
    if hh == 0:
        disp_h = 12
    elif hh > 12:
        disp_h = hh - 12
    else:
        disp_h = hh
    return f"{disp_h}:{mm:02d}{ampm}"

