]

start_location = 'Bayview'
start_time = to_minutes('9:00AM')

# DFS with pruning to maximize number of friends met
best_schedule: List[str] = []
best_count: int = 0
best_finish_time: int = 10**9

from functools import lru_cache

# For ordering/pruning, try friends in a heuristic order (earlier end first)
friends_sorted_idx = sorted(range(len(friends)), key=lambda i: friends[i][3])

@lru_cache(None)
def optimistic_remaining(current_met_mask: int) -> int:
    # Count of friends not met yet
    return len(friends) - bin(current_met_mask).count('1')

def dfs(current_loc: str, current_time: int, met_mask: int, actions: List[str]):
    global best_schedule, best_count, best_finish_time

    met_count = bin(met_mask).count('1')
    # Update best
    if (met_count > best_count) or (met_count == best_count and current_time < best_finish_time):
        best_count = met_count
        best_schedule = actions[:]
        best_finish_time = current_time

    # Prune if even meeting everyone else can't beat current best
    remaining = len(friends) - met_count
    if met_count + remaining < best_count:
        return

    # Try all not-yet-met friends
    for idx in friends_sorted_idx:
        if (met_mask >> idx) & 1:
            continue
        name, loc, start, end, mindur = friends[idx]

        # Travel time
        if current_loc not in times or loc not in times[current_loc]:
            continue  # if no direct travel time
        travel = times[current_loc][loc]
        arrive = current_time + travel
        meet_start = max(arrive, start)
        meet_end = meet_start + mindur
        if meet_end <= end:
            # Build action logs
            new_actions = actions[:]
            if travel > 0:
                new_actions.append(f"You travel to {loc} in {travel} minutes and arrive at {fmt_time(arrive)}.")
            else:
                # same location jump
                new_actions.append(f"You stay at {loc} and it is {fmt_time(arrive)}.")
            if arrive < meet_start:
                new_actions.append(f"You wait until {fmt_time(meet_start)}.")
            new_actions.append(f"You meet {name} for {mindur} minutes from {fmt_time(meet_start)} to {fmt_time(meet_end)}.")
            dfs(loc, meet_end, met_mask | (1 << idx), new_actions)

# Initialize and run
initial_actions = [f"You start at {start_location} at {fmt_time(start_time)}."]

# You can also optionally insert an initial travel to anywhere; DFS handles that naturally by trying friends from Bayview

dfs(start_location, start_time, 0, initial_actions)

# Print the best schedule found
print(best_schedule)

